#!/usr/bin/env bash
#
# Builds the Claude Code plugin in plugin/ from the kit's single source in .ai-kit/.
#
# plugin/ is committed: it is what the plugin directory and /plugin install. Hand-written files there
# (.claude-plugin/plugin.json, .claude-plugin/icon.png, README.md) are kept; everything else is
# generated by this script. Run it after any change in .ai-kit/skills, .ai-kit/agents or
# .ai-kit/instructions, and commit the result. CI fails when plugin/ is out of date.
#
# What the plugin gets:
#   .ai-kit/skills/<name>/   -> plugin/skills/<name>/   without <skill>/agents/ (Codex-only)
#   .ai-kit/agents/*.md      -> plugin/agents/*.md      without the `codex: |` frontmatter block
#   .ai-kit/instructions/    -> plugin/instructions/
#   LICENSE                  -> plugin/LICENSE
# Paths to .ai-kit/instructions/ become ${CLAUDE_PLUGIN_ROOT}/instructions/, which Claude Code
# resolves in skill and agent content.
#
# Left out: skills that only work with the full kit in the project (listed in kit_only).

set -euo pipefail

cd "$(dirname "$0")/.."

out=plugin
kit_only=(generate-agents-md)

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

# Prints a subagent file without the `codex: |` block of its frontmatter.
claude_agent() {
  awk '
    /^---$/ { n++ }
    n == 1 && $0 == "codex: |" { block = 1; next }
    block && /^  / { next }
    { block = 0; print }
  ' "$1"
}

excludes=(--exclude .DS_Store --exclude '/*/agents/')
for name in "${kit_only[@]}"; do
  excludes+=(--exclude "/$name/")
done

mkdir -p "$tmp/skills" "$tmp/agents" "$tmp/instructions"
rsync -a "${excludes[@]}" .ai-kit/skills/ "$tmp/skills/"
rsync -a --exclude .DS_Store .ai-kit/instructions/ "$tmp/instructions/"
for md in .ai-kit/agents/*.md; do
  claude_agent "$md" > "$tmp/agents/$(basename "$md")"
done

# The guides live in the plugin, not in the project.
find "$tmp" -type f -name '*.md' -print0 | while IFS= read -r -d '' file; do
  # shellcheck disable=SC2016 # ${CLAUDE_PLUGIN_ROOT} is literal text for Claude Code.
  sed -i.bak 's#\.ai-kit/instructions/#${CLAUDE_PLUGIN_ROOT}/instructions/#g' "$file"
  rm -f "$file.bak"
done

for dir in skills agents instructions; do
  mkdir -p "$out/$dir"
  rsync -a --delete --checksum "$tmp/$dir/" "$out/$dir/"
done
cp LICENSE "$out/LICENSE"

echo "plugin/: $(find "$out/skills" -name SKILL.md | wc -l | tr -d ' ') skills, $(find "$out/agents" -name '*.md' | wc -l | tr -d ' ') agents."
